import io

TEXT = "2026-03-01 INFO start\n2026-03-01 ERROR disk full\n\n2026-03-02 WARN slow\n2026-03-02 ERROR timeout\n2026-03-03 INFO done\n2026-03-03 ERROR bad row 7\n"

def lines(f):
    for line in f:
        line = line.strip()
        if line:
            yield line

def errors(rows):
    for row in rows:
        parts = row.split(maxsplit=2)
        if parts[1] == "ERROR":
            yield parts[2]

def numbered(messages):
    for position, message in enumerate(messages, start=1):
        yield position, message

for number, message in numbered(errors(lines(io.StringIO(TEXT)))):
    print(f"{number}: {message}")
print(sum(1 for _ in errors(lines(io.StringIO(TEXT)))))
